import { v7 as uuidv7, validate } from 'uuid';

import { DomainError } from '../errors/domain-error.ts';

export class InvalidIdentifierError extends DomainError {
  constructor(value: string) {
    super(`"${value}" is not a valid identifier`);
  }
}

/**
 * Base class for strongly-typed ids (`UserId`, `SessionId`, …). Ids are UUIDv7: time-ordered,
 * so they index well in Postgres and can be generated by the domain before persistence.
 */
export abstract class Identifier {
  protected constructor(readonly value: string) {}

  protected static newValue(): string {
    return uuidv7();
  }

  protected static assertValid(value: string): string {
    if (!validate(value)) throw new InvalidIdentifierError(value);
    return value;
  }

  equals(other?: Identifier | null): boolean {
    return !!other && other.constructor === this.constructor && other.value === this.value;
  }

  toString(): string {
    return this.value;
  }
}
